class Invoice:
    def __init__(self, items, discount=0.0):
        self.items = items
        self.discount = discount

    def subtotal(self):
        return sum(q * p for q, p in self.items)

    def total(self):
        total = self.subtotal()
        if self.discount > 0:
            total - total * self.discount
        return round(total, 2)

