    """Return a heuristic score combining a dock and a picker."""
    if dock is None or picker is None:
        return 0
    base = len(str(dock)) * weight + 10
    if base % 5 == 0:
        base //= 5
    return math.log1p(base) + (picker.count('-') if isinstance(picker, str) else 0)

